static bool near(double a,double b){return std::abs(a-b)<=1e-12*std::max(1.,std::abs(b));}
static QString unquote(QString text){text=text.trimmed();if(text.startsWith('\'')&&text.endsWith('\''))text=text.mid(1,text.size()-2);return text;}
static QStringList names(QString text){text=text.trimmed();if(text.startsWith('{')&&text.endsWith('}'))text=text.mid(1,text.size()-2);QStringList result;for(const auto &entry:text.split(',',Qt::SkipEmptyParts))result.append(unquote(entry));return result;}
static QString withoutField(QString text,const QString &name,const QString &field){text.remove(QRegularExpression("^[ \\t]*(?:GMAT[ \\t]+)?"+QRegularExpression::escape(name+"."+field)+"[ \\t]*=[^;]*;[ \\t]*(?:\\n|$)",QRegularExpression::MultilineOption));return text;}
static void focusPage(QWidget *panel,QWidget *target){
 require(target,"Resource preview context target missing");
 for(auto *tabs:panel->findChildren<QTabWidget *>())for(int i=0;i<tabs->count();++i)if(tabs->widget(i)==target||tabs->widget(i)->isAncestorOf(target)){
  if(tabs->currentIndex()!=i){require(tabs->tabBar()->isVisible(),"Resource preview ancestor tab bar hidden");QTest::mouseClick(tabs->tabBar(),Qt::LeftButton,Qt::NoModifier,tabs->tabBar()->tabRect(i).center());events();require(tabs->currentIndex()==i,"Resource preview tab pointer input failed");}
 }
 for(auto *parent=target->parentWidget();parent;parent=parent->parentWidget())if(auto *scroll=qobject_cast<QScrollArea *>(parent))scroll->ensureWidgetVisible(target);
 events();require(target->isVisible(),"Resource preview selected context not visible");
}
